//! Narrative summary compaction for context trims.
//!
//! When the runtime must shrink the provider transcript, the historical
//! behavior drops whole turns and leaves a static breadcrumb — the model
//! "wakes up" mid-task with no memory of the removed work. With
//! `[runtime_profiles.<alias>.context_compression] enabled`, the trim pipeline
//! instead compresses the removable span into ONE first-person narrative
//! summary generated by an LLM call, replacing the span in place.
//!
//! Invariants (see the feature architecture doc):
//! - I1: leading system messages never enter the compaction span.
//! - I2: genuine user messages never enter the summary input — they are kept
//!   verbatim in the transcript; only agent work (assistant/tool rows and
//!   prompt-mode tool-result carriers) is summarized.
//! - I3: with the config disabled the engine is never invoked.
//! - I4: any summarizer failure leaves the history untouched so the caller
//!   can run its existing breadcrumb trim.
//!
//! The span itself is chosen by the caller: every trim trigger already
//! computes exactly which oldest whole turns it would drop, and this module
//! consumes that decision (`span_len`) rather than re-deriving it. That keeps
//! compaction span semantics identical to the breadcrumb span semantics by
//! construction.

use crate::agent::history::estimate_history_tokens;
use zeroclaw_providers::{ChatMessage, ChatRequest, ModelProvider};

/// Structural marker prefix of a compaction summary message. Mirrors the
/// `PRUNED_TOOL_EXCHANGE_SUMMARY_PREFIX` convention: an internal, English,
/// model-facing marker identified by prefix + role, so it persists through
/// session stores and resyncs as an ordinary transcript row and is
/// distinguishable from real user turns.
pub(crate) const COMPACTION_SUMMARY_PREFIX: &str = "[Compaction summary:";

/// CostTracker scope for summary-compaction LLM calls (FR8).
pub(crate) const COST_SCOPE: &str = "context_compaction";

/// First-person narrative system prompt. Model-facing runtime text (same
/// class as tool instructions), English per the logging/text contract.
const SUMMARY_SYSTEM_PROMPT: &str = "You are compacting an agent's conversation \
history. You will receive earlier agent work — assistant replies, tool calls, \
and tool results — that no longer fits the context window. The user's own \
messages are kept verbatim elsewhere and must not be restated. Write a \
first-person narrative summary from the agent's perspective in present-perfect \
tense covering exactly four things: what was done, what was established, what \
is in progress, and what remains unknown. Preserve concrete facts the agent \
would need to continue: file paths, identifiers, commands, decisions, and \
error messages. Do not invent facts and do not address the user. Stay under \
the stated token budget.";

/// True when `msg` is a compaction summary marker rather than a genuine
/// transcript row.
pub(crate) fn is_compaction_summary(msg: &ChatMessage) -> bool {
    msg.role == "user" && msg.content.starts_with(COMPACTION_SUMMARY_PREFIX)
}

/// Which reduction ran for one trim event.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CompactionMode {
    /// The removed span was replaced by one narrative summary message.
    Summary,
    /// The existing static-breadcrumb whole-turn trim ran.
    Breadcrumb,
}

/// The caller-selected removable span, partitioned for compaction.
#[derive(Debug, Clone)]
pub(crate) struct CompactionSpan {
    /// Contiguous transcript rows the caller's trim would drop.
    pub(crate) range: std::ops::Range<usize>,
    /// Agent-work rows to feed the summarizer, in original order.
    pub(crate) summary_input: Vec<ChatMessage>,
    /// Genuine user messages inside the span, kept verbatim in original
    /// order (I2).
    pub(crate) kept_users: Vec<ChatMessage>,
    /// Estimated tokens of `summary_input` — the number `trigger_tokens`
    /// gates on.
    pub(crate) span_tokens: usize,
}

/// A user message is a genuine turn head when it is neither a prompt-mode
/// tool-result carrier nor a compaction summary marker. Breadcrumb rows
/// cannot appear inside the span: the owner-recorded crumb sits before the
/// body by contract.
fn is_genuine_user_message(msg: &ChatMessage) -> bool {
    msg.role == "user"
        && !msg
            .content
            .starts_with(zeroclaw_api::tool_carrier::TOOL_RESULTS_PREFIX)
        && !is_compaction_summary(msg)
}

/// Partition the caller-selected span into summarizable agent work and
/// verbatim-kept user messages. `span_len` is the number of body rows the
/// caller's trim would drop (e.g. `TrimResult::dropped_messages` or
/// `drop_oldest_whole_turn`'s return); `crumb_present` is the owner's
/// authoritative record that a synthetic breadcrumb sits immediately after
/// the leading system messages.
///
/// Returns `None` when there is nothing worth summarizing: no removable rows,
/// no agent work in the span, or the agent work is below `trigger_tokens`
/// estimated tokens (a summary round-trip is not worth it for a tiny span;
/// the caller's breadcrumb trim runs instead).
pub(crate) fn select_compaction_span(
    history: &[ChatMessage],
    crumb_present: bool,
    span_len: usize,
    trigger_tokens: usize,
) -> Option<CompactionSpan> {
    let leading_system = history.iter().take_while(|m| m.role == "system").count();
    let body_start = leading_system + usize::from(crumb_present);
    if span_len == 0 || body_start >= history.len() {
        return None;
    }
    let range = body_start..(body_start + span_len).min(history.len());
    if range.is_empty() {
        return None;
    }

    let mut summary_input = Vec::new();
    let mut kept_users = Vec::new();
    for msg in &history[range.clone()] {
        if is_genuine_user_message(msg) {
            kept_users.push(msg.clone());
        } else {
            summary_input.push(msg.clone());
        }
    }
    if summary_input.is_empty() {
        return None;
    }
    let span_tokens = estimate_history_tokens(&summary_input);
    if span_tokens < trigger_tokens {
        return None;
    }
    Some(CompactionSpan {
        range,
        summary_input,
        kept_users,
        span_tokens,
    })
}

/// One LLM round-trip that compresses `span_input` into a first-person
/// narrative. Returns the summary text, the provider-reported usage (when
/// available), and the locally estimated input tokens of the request.
/// Errors propagate so the caller can fall back (I4); an empty/whitespace
/// summary is an error for the same reason.
pub(crate) async fn summarize_span(
    summarizer: &dyn ModelProvider,
    model: &str,
    span_input: &[ChatMessage],
    max_output_tokens: u32,
) -> anyhow::Result<(
    String,
    Option<zeroclaw_api::model_provider::TokenUsage>,
    usize,
)> {
    let budget_note = format!(
        "Token budget for the summary: at most {max_output_tokens} tokens.\n\n\
         Earlier agent work to summarize:\n{}",
        span_input
            .iter()
            .map(|m| format!("{}: {}", m.role, m.content))
            .collect::<Vec<_>>()
            .join("\n")
    );
    let messages = [
        ChatMessage::system(SUMMARY_SYSTEM_PROMPT),
        ChatMessage::user(budget_note),
    ];
    let input_estimate = estimate_history_tokens(&messages);
    let response = summarizer
        .chat(
            ChatRequest {
                messages: &messages,
                tools: None,
                thinking: None,
            },
            model,
            None,
        )
        .await?;
    let text = zeroclaw_api::model_provider::strip_think_tags(response.text_or_empty());
    if text.is_empty() {
        anyhow::bail!("compaction summarizer returned an empty summary");
    }
    Ok((text, response.usage, input_estimate))
}

/// Outcome of one successful compaction; also used (via [`CompactionMode::Breadcrumb`])
/// to describe a fallback so observability can report both shapes uniformly.
#[derive(Debug, Clone)]
pub(crate) struct CompactionOutcome {
    pub(crate) mode: CompactionMode,
    /// Rows the caller's trim removed from the span (before replacement).
    pub(crate) span_messages: usize,
    /// Estimated tokens of the summarized agent work.
    pub(crate) span_tokens: usize,
    /// Genuine user messages kept verbatim out of the span.
    pub(crate) kept_user_messages: usize,
    /// The verbatim-kept user rows, in splice order (summary first, then
    /// these) — the trim trigger mirrors them into its rebuilt request.
    pub(crate) kept_users: Vec<ChatMessage>,
    /// The synthetic summary message now in the transcript.
    pub(crate) summary: Option<ChatMessage>,
    /// Tokens of the accepted summary (reported, else estimated).
    pub(crate) summary_tokens: usize,
    /// `provider/model` label used for the summary call (event payload).
    pub(crate) provider: String,
    /// True when the breadcrumb trim ran because compaction failed (I4).
    pub(crate) fell_back: bool,
}

impl CompactionOutcome {
    /// Outcome describing a breadcrumb fallback after a failed or skipped
    /// compaction attempt. `provider` names the route that WOULD have served
    /// the summary, so the event still tells operators where to look.
    pub(crate) fn breadcrumb_fallback(
        span_messages: usize,
        span_tokens: usize,
        provider: String,
    ) -> Self {
        Self {
            mode: CompactionMode::Breadcrumb,
            span_messages,
            span_tokens,
            kept_user_messages: 0,
            kept_users: Vec::new(),
            summary: None,
            summary_tokens: 0,
            provider,
            fell_back: true,
        }
    }
}

/// Map an engine outcome to the public event payload attached to
/// `TurnEvent::HistoryTrimmed` (FR9).
pub(crate) fn event_info(
    outcome: &CompactionOutcome,
) -> zeroclaw_api::agent::ContextCompactionInfo {
    zeroclaw_api::agent::ContextCompactionInfo {
        mode: match outcome.mode {
            CompactionMode::Summary => "summary",
            CompactionMode::Breadcrumb => "breadcrumb",
        },
        span_messages: outcome.span_messages,
        span_tokens: outcome.span_tokens,
        summary_tokens: outcome.summary_tokens,
        kept_user_messages: outcome.kept_user_messages,
        provider: outcome.provider.clone(),
        fell_back: outcome.fell_back,
    }
}

/// Structured trace record for one compaction event (FR9). Emitted on every
/// successful summary replacement; `trigger` names the trim seam
/// ("pre_dispatch" | "reported_budget" | "overflow_recovery").
pub(crate) fn record_compaction_trace(outcome: &CompactionOutcome, trigger: &str) {
    let mode = match outcome.mode {
        CompactionMode::Summary => "summary",
        CompactionMode::Breadcrumb => "breadcrumb",
    };
    ::zeroclaw_log::record!(
        INFO,
        ::zeroclaw_log::Event::new(module_path!(), ::zeroclaw_log::Action::Complete)
            .with_category(::zeroclaw_log::EventCategory::Agent)
            .with_outcome(::zeroclaw_log::EventOutcome::Success)
            .with_attrs(::serde_json::json!({
                "trigger": trigger,
                "mode": mode,
                "span_messages": outcome.span_messages,
                "span_tokens": outcome.span_tokens,
                "summary_tokens": outcome.summary_tokens,
                "kept_user_messages": outcome.kept_user_messages,
                "provider": outcome.provider,
                "fell_back": outcome.fell_back,
                "cost_scope": COST_SCOPE,
            })),
        "Context compaction: history span replaced by narrative summary"
    );
}

/// Attempt to replace the caller-selected span with one narrative summary.
///
/// Mutates `history` ONLY on success; on any failure (disabled config, empty
/// or sub-threshold span, summarizer error, empty summary, or a summary whose
/// provider-reported output exceeds `summary_max_output_tokens`) the history
/// is left untouched and `None` is returned so the caller runs its existing
/// breadcrumb trim — the turn never fails because of compaction (I4).
///
/// `span_len` must be the number of body rows the caller's own trim would
/// drop, so compaction removes exactly what the breadcrumb would have removed.
pub(crate) async fn compact_history(
    history: &mut Vec<ChatMessage>,
    crumb_present: bool,
    span_len: usize,
    cfg: &zeroclaw_config::scattered_types::ContextCompressionConfig,
    summarizer: &dyn ModelProvider,
    summarizer_provider: &str,
    summarizer_model: &str,
) -> Option<CompactionOutcome> {
    if !cfg.enabled {
        return None;
    }
    let span = select_compaction_span(history, crumb_present, span_len, cfg.trigger_tokens)?;
    let provider = format!("{summarizer_provider}/{summarizer_model}");
    let (text, usage, input_estimate) = match summarize_span(
        summarizer,
        summarizer_model,
        &span.summary_input,
        cfg.summary_max_output_tokens,
    )
    .await
    {
        Ok(summary) => summary,
        Err(error) => {
            ::zeroclaw_log::record!(
                WARN,
                ::zeroclaw_log::Event::new(module_path!(), ::zeroclaw_log::Action::Fail)
                    .with_category(::zeroclaw_log::EventCategory::Agent)
                    .with_outcome(::zeroclaw_log::EventOutcome::Failure)
                    .with_attrs(::serde_json::json!({
                        "error": format!("{error:#}"),
                        "provider": provider,
                        "span_messages": span.range.len(),
                        "fallback": "breadcrumb",
                    })),
                "Context compaction: summarizer failed, falling back to breadcrumb trim"
            );
            return None;
        }
    };
    let reported_output_tokens = usage.as_ref().and_then(|u| u.output_tokens);
    if let Some(output_tokens) = reported_output_tokens
        && output_tokens > cfg.summary_max_output_tokens as u64
    {
        ::zeroclaw_log::record!(
            WARN,
            ::zeroclaw_log::Event::new(module_path!(), ::zeroclaw_log::Action::Fail)
                .with_category(::zeroclaw_log::EventCategory::Agent)
                .with_outcome(::zeroclaw_log::EventOutcome::Failure)
                .with_attrs(::serde_json::json!({
                    "output_tokens": output_tokens,
                    "summary_max_output_tokens": cfg.summary_max_output_tokens,
                    "provider": provider,
                    "fallback": "breadcrumb",
                })),
            "Context compaction: summary exceeded its token budget, falling back to breadcrumb trim"
        );
        return None;
    }
    // FR8: attribute the summary round-trip to the session's CostTracker
    // under the distinct `context_compaction` scope. Providers that report
    // usage are priced on the report; the rest are estimated locally
    // (input estimate from the request, output at ~4 chars/token).
    let input_tokens = usage
        .as_ref()
        .and_then(|u| u.input_tokens)
        .unwrap_or(input_estimate as u64);
    let output_tokens = reported_output_tokens.unwrap_or((text.len() / 4).max(1) as u64);
    crate::agent::cost::record_context_compaction_cost_usage(
        summarizer_provider,
        summarizer_model,
        &zeroclaw_providers::traits::TokenUsage {
            input_tokens: Some(input_tokens),
            output_tokens: Some(output_tokens),
            cached_input_tokens: None,
            cache_creation_input_tokens: None,
        },
    );
    let summary_tokens = reported_output_tokens
        .map(|tokens| usize::try_from(tokens).unwrap_or(usize::MAX))
        .unwrap_or_else(|| text.len() / 4);
    let summary = ChatMessage::user(format!(
        "{COMPACTION_SUMMARY_PREFIX} {} earlier message(s) condensed]\n{text}",
        span.summary_input.len()
    ))
    .with_origin(zeroclaw_api::model_provider::MessageOrigin::CompactionSummary);
    let kept_user_messages = span.kept_users.len();
    let kept_users = span.kept_users.clone();
    history.splice(
        span.range.clone(),
        std::iter::once(summary.clone()).chain(span.kept_users),
    );
    Some(CompactionOutcome {
        mode: CompactionMode::Summary,
        span_messages: span.range.len(),
        span_tokens: span.span_tokens,
        kept_user_messages,
        kept_users,
        summary: Some(summary),
        summary_tokens,
        provider,
        fell_back: false,
    })
}

/// Per-turn resolution of `[runtime_profiles.<alias>.context_compression]`:
/// whether compaction runs at all and which route serves the summarizer.
/// Built once per tool-call loop from the live `Config`, mirroring how
/// `ResolvedAgentExecution` snapshots the turn's other runtime knobs. When
/// the plan is absent (no config, no runtime profile, or the feature off)
/// every `maybe_compact` call short-circuits and the trim pipeline is
/// identical to a build without compaction (I3).
pub(crate) struct CompactionPlanner {
    plan: Option<CompactionPlan>,
}

struct CompactionPlan {
    /// Snapshot of the revived profile block; `enabled` is always true here
    /// (the planner is disabled otherwise), `summary_provider` stays on the
    /// config — route selection is the planner's job.
    cfg: zeroclaw_config::scattered_types::ContextCompressionConfig,
    route: CompactionRoute,
}

enum CompactionRoute {
    /// Summarize with the provider/model that serves the current turn.
    TurnModel,
    /// A configured `summary_provider` override resolved from Config.
    Override {
        provider: Box<dyn ModelProvider>,
        name: String,
        /// Alias-owned model; `None` for bare-family refs, which then reuse
        /// the turn's model on the override provider.
        model: Option<String>,
    },
}

impl CompactionPlanner {
    /// Inert planner: every trigger falls straight to its breadcrumb trim.
    pub(crate) fn disabled() -> Self {
        Self { plan: None }
    }

    /// Resolve the agent's compaction plan from the live config. A broken
    /// `summary_provider` override (unbuildable at runtime despite passing
    /// config validation) degrades to the turn's own provider instead of
    /// disabling compaction — the feature still works, just not routed.
    pub(crate) fn resolve(
        config: Option<&zeroclaw_config::schema::Config>,
        agent_alias: Option<&str>,
    ) -> Self {
        let (Some(config), Some(alias)) = (config, agent_alias) else {
            return Self::disabled();
        };
        let Some(profile) = config.runtime_profile_for_agent(alias) else {
            return Self::disabled();
        };
        let cfg = profile.context_compression.clone();
        if !cfg.enabled {
            return Self::disabled();
        }
        let route = config
            .effective_summary_provider(alias)
            .filter(|provider_ref| !provider_ref.trim().is_empty())
            .map(|provider_ref| {
                let name = provider_ref.trim().to_string();
                match zeroclaw_providers::create_model_provider_from_ref_with_model(config, &name) {
                    Ok(resolved) => CompactionRoute::Override {
                        provider: resolved.provider,
                        name,
                        model: resolved.model,
                    },
                    Err(error) => {
                        ::zeroclaw_log::record!(
                            WARN,
                            ::zeroclaw_log::Event::new(
                                module_path!(),
                                ::zeroclaw_log::Action::Note
                            )
                            .with_category(::zeroclaw_log::EventCategory::Agent)
                            .with_outcome(::zeroclaw_log::EventOutcome::Unknown)
                            .with_attrs(::serde_json::json!({
                                "provider": name,
                                "error": format!("{error:#}"),
                            })),
                            "Context compaction: summary_provider override could not be built; \
                             falling back to the turn's provider"
                        );
                        CompactionRoute::TurnModel
                    }
                }
            })
            .unwrap_or(CompactionRoute::TurnModel);
        Self {
            plan: Some(CompactionPlan { cfg, route }),
        }
    }

    pub(crate) fn is_enabled(&self) -> bool {
        self.plan.is_some()
    }

    /// `provider/model` label of the route a summary takes (or would take on
    /// fallback) — used to attribute events and traces.
    pub(crate) fn provider_label(&self, turn_provider: &str, turn_model: &str) -> String {
        match &self.plan {
            Some(plan) => match &plan.route {
                CompactionRoute::TurnModel => format!("{turn_provider}/{turn_model}"),
                CompactionRoute::Override { name, model, .. } => {
                    format!("{name}/{}", model.as_deref().unwrap_or(turn_model))
                }
            },
            None => format!("{turn_provider}/{turn_model}"),
        }
    }

    /// Attempt to replace the caller-selected span (`span_len` body rows,
    /// exactly what the caller's own breadcrumb trim would drop) with one
    /// narrative summary. Returns the outcome on success; on any failure the
    /// history is untouched and `None` lets the caller run its existing
    /// breadcrumb trim (I4). Never fails the turn.
    pub(crate) async fn maybe_compact(
        &self,
        trigger: &str,
        history: &mut Vec<ChatMessage>,
        crumb_present: bool,
        span_len: usize,
        turn_provider: &dyn ModelProvider,
        turn_provider_name: &str,
        turn_model: &str,
    ) -> Option<CompactionOutcome> {
        let plan = self.plan.as_ref()?;
        // Spend no money on a summary when the tool-loop budget is exhausted:
        // degrade to the free breadcrumb trim instead of erroring the turn.
        if matches!(
            crate::agent::cost::check_tool_loop_budget(),
            Some(crate::cost::types::BudgetCheck::Exceeded { .. })
        ) {
            ::zeroclaw_log::record!(
                WARN,
                ::zeroclaw_log::Event::new(module_path!(), ::zeroclaw_log::Action::Reject)
                    .with_category(::zeroclaw_log::EventCategory::Agent)
                    .with_outcome(::zeroclaw_log::EventOutcome::Failure)
                    .with_attrs(::serde_json::json!({
                        "fallback": "breadcrumb",
                    })),
                "Context compaction skipped: tool-loop budget exhausted"
            );
            return None;
        }
        let (provider, provider_name, model) = match &plan.route {
            CompactionRoute::TurnModel => (turn_provider, turn_provider_name, turn_model),
            CompactionRoute::Override {
                provider,
                name,
                model,
            } => (
                provider.as_ref(),
                name.as_str(),
                model.as_deref().unwrap_or(turn_model),
            ),
        };
        let outcome = compact_history(
            history,
            crumb_present,
            span_len,
            &plan.cfg,
            provider,
            provider_name,
            model,
        )
        .await;
        if let Some(done) = outcome.as_ref() {
            record_compaction_trace(done, trigger);
        }
        outcome
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use zeroclaw_api::attribution::{Attributable, ModelProviderKind, ProviderKind, Role};
    use zeroclaw_config::scattered_types::ContextCompressionConfig;
    use zeroclaw_providers::ChatResponse;

    fn sys(c: &str) -> ChatMessage {
        ChatMessage::system(c)
    }
    fn user(c: &str) -> ChatMessage {
        ChatMessage::user(c)
    }
    fn asst(c: &str) -> ChatMessage {
        ChatMessage::assistant(c)
    }
    fn tool(c: &str) -> ChatMessage {
        ChatMessage::tool(c)
    }

    fn tool_results_carrier(c: &str) -> ChatMessage {
        user(&format!(
            "{}\n{c}",
            zeroclaw_api::tool_carrier::TOOL_RESULTS_PREFIX
        ))
    }

    /// ChatMessage has no PartialEq; the history tests compare through the
    /// persisted JSON form, the same shape session storage sees.
    fn history_json(history: &[ChatMessage]) -> serde_json::Value {
        serde_json::to_value(history).expect("history serializes")
    }

    fn assert_message_eq(actual: &ChatMessage, expected: &ChatMessage) {
        assert_eq!(
            (actual.role.as_str(), actual.content.as_str()),
            (expected.role.as_str(), expected.content.as_str()),
            "message mismatch: {actual:?}"
        );
    }

    fn enabled_config() -> ContextCompressionConfig {
        ContextCompressionConfig {
            enabled: true,
            trigger_tokens: 0,
            summary_max_output_tokens: 500,
            ..ContextCompressionConfig::default()
        }
    }

    /// Scripted summarizer: returns `text` (or `err`) and records the request
    /// it was given so tests can assert the exemption invariants.
    struct MockSummarizer {
        result: std::result::Result<String, String>,
        usage_output_tokens: Option<u64>,
        seen_request: std::sync::Mutex<Vec<ChatMessage>>,
    }

    impl MockSummarizer {
        fn text(text: &str) -> Self {
            Self {
                result: Ok(text.to_string()),
                usage_output_tokens: Some(120),
                seen_request: std::sync::Mutex::new(Vec::new()),
            }
        }
        fn error() -> Self {
            Self {
                result: Err("summarizer unavailable".to_string()),
                usage_output_tokens: None,
                seen_request: std::sync::Mutex::new(Vec::new()),
            }
        }
        fn seen_messages(&self) -> Vec<ChatMessage> {
            self.seen_request.lock().expect("mock lock").clone()
        }
    }

    impl Attributable for MockSummarizer {
        fn role(&self) -> Role {
            Role::Provider(ProviderKind::Model(ModelProviderKind::Custom))
        }
        fn alias(&self) -> &str {
            "mock-summarizer"
        }
    }

    #[async_trait::async_trait]
    impl ModelProvider for MockSummarizer {
        async fn chat_with_system(
            &self,
            _system_prompt: Option<&str>,
            _message: &str,
            _model: &str,
            _temperature: Option<f64>,
        ) -> anyhow::Result<String> {
            unimplemented!("compaction uses the structured chat API")
        }
        async fn chat(
            &self,
            request: ChatRequest<'_>,
            _model: &str,
            _temperature: Option<f64>,
        ) -> anyhow::Result<ChatResponse> {
            *self.seen_request.lock().expect("mock lock") = request.messages.to_vec();
            let text = self
                .result
                .clone()
                .map_err(|error| anyhow::anyhow!(error))?;
            Ok(ChatResponse {
                text: Some(text),
                tool_calls: Vec::new(),
                usage: self.usage_output_tokens.map(|output_tokens| {
                    zeroclaw_api::model_provider::TokenUsage {
                        input_tokens: Some(1_000),
                        output_tokens: Some(output_tokens),
                        cached_input_tokens: None,
                        cache_creation_input_tokens: None,
                    }
                }),
                reasoning_content: None,
            })
        }
    }

    /// Tool-heavy history: one system message, then three user-headed turns
    /// with large tool payloads. `drop_oldest_whole_turn`-style removal of the
    /// first two turns yields `span_len` rows for compaction.
    fn long_history() -> Vec<ChatMessage> {
        let big = "x".repeat(4_000);
        vec![
            sys("system instructions"),
            user("turn one request"),
            asst(&format!("tool work one {big}")),
            tool(&format!("tool result one {big}")),
            asst("interim one"),
            user("turn two request"),
            asst(&format!("tool work two {big}")),
            tool(&format!("tool result two {big}")),
            user("turn three request"),
            asst("current answer"),
        ]
    }

    #[test]
    fn select_span_keeps_user_messages_verbatim_and_never_includes_system() {
        let history = long_history();
        // The caller's trim would drop the first two whole turns: rows 1..=6
        // (after the leading system), i.e. span_len = 6 starting at body 1.
        let span = select_compaction_span(&history, false, 6, 0).expect("span selectable");
        assert_eq!(span.range, 1..7);
        // I1: the system prefix is never part of the span.
        assert!(
            !history[span.range.clone()]
                .iter()
                .any(|m| m.role == "system"),
            "system prompt bytes must never enter the compaction span"
        );
        // I2: genuine user messages are exempt from the summary input…
        assert_eq!(span.kept_users.len(), 2);
        assert_message_eq(&span.kept_users[0], &user("turn one request"));
        assert_message_eq(&span.kept_users[1], &user("turn two request"));
        // …and the summary input is exactly the agent work between them.
        assert_eq!(span.summary_input.len(), 4);
        assert!(
            span.summary_input
                .iter()
                .all(|m| m.role == "assistant" || m.role == "tool"),
            "summary input must be agent work only, got {:?}",
            span.summary_input
                .iter()
                .map(|m| &m.role)
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn select_span_treats_tool_result_carriers_as_agent_work() {
        let history = vec![
            sys("s"),
            user("old request"),
            asst("calling tool"),
            tool_results_carrier("raw result"),
            user("new request"),
            asst("new answer"),
        ];
        let span = select_compaction_span(&history, false, 3, 0).expect("span selectable");
        // The prompt-mode tool-result carrier is user-role text but NOT a
        // genuine user message: it summarizes with its turn's tool work. The
        // turn head ("old request") is genuine and stays verbatim.
        assert_message_eq(&span.kept_users[0], &user("old request"));
        assert_eq!(span.summary_input.len(), 2);
        assert_message_eq(&span.summary_input[0], &asst("calling tool"));
        assert_message_eq(&span.summary_input[1], &tool_results_carrier("raw result"));
    }

    #[test]
    fn select_span_respects_owner_crumb_record() {
        let mut history = vec![sys("s"), crate::agent::history_trim::breadcrumb()];
        history.extend(long_history().into_iter().skip(1));
        let span = select_compaction_span(&history, true, 6, 0).expect("span selectable");
        // body_start = 1 (system) + 1 (owner-recorded crumb) = 2.
        assert_eq!(span.range, 2..8);
        assert_eq!(span.kept_users.len(), 2);
    }

    #[test]
    fn select_span_rejects_empty_and_sub_threshold_spans() {
        let history = long_history();
        assert!(select_compaction_span(&history, false, 0, 0).is_none());
        // trigger above the whole history: nothing is worth a round-trip.
        assert!(select_compaction_span(&history, false, 6, usize::MAX).is_none());
        // A span of only user messages has no agent work to summarize.
        let users_only = vec![sys("s"), user("a"), user("b"), user("c")];
        assert!(select_compaction_span(&users_only, false, 2, 0).is_none());
    }

    #[tokio::test]
    async fn compact_history_replaces_span_with_marked_first_person_summary() {
        let mut history = long_history();
        let before_len = history.len();
        let mock = MockSummarizer::text(
            "I have scanned the repository and established the build layout. \
             I was fixing the trim pipeline and remain unsure about the test count.",
        );
        let outcome = compact_history(
            &mut history,
            false,
            6,
            &enabled_config(),
            &mock,
            "custom.default",
            "m-main",
        )
        .await
        .expect("compaction succeeds");

        assert_eq!(outcome.mode, CompactionMode::Summary);
        assert!(!outcome.fell_back);
        assert_eq!(outcome.span_messages, 6);
        assert!(outcome.span_tokens > 0);
        assert_eq!(outcome.kept_user_messages, 2);
        assert_eq!(outcome.summary_tokens, 120);
        assert_eq!(outcome.provider, "custom.default/m-main");

        // Span replaced by ONE summary message + the two kept user rows.
        assert_eq!(history.len(), before_len - 6 + 1 + 2);
        let summary_pos = history
            .iter()
            .position(is_compaction_summary)
            .expect("summary marker present");
        let summary = &history[summary_pos];
        assert!(
            is_compaction_summary(summary),
            "summary is structurally marked: {summary:?}"
        );
        // The exempt user messages survive verbatim, in original order, right
        // after the summary.
        assert_message_eq(&history[summary_pos + 1], &user("turn one request"));
        assert_message_eq(&history[summary_pos + 2], &user("turn two request"));
        // The retained newest turn is untouched.
        assert_message_eq(history.last().expect("nonempty"), &asst("current answer"));
        // The system prefix survived untouched (I1).
        assert_message_eq(&history[0], &sys("system instructions"));

        // The LLM saw only the fixed system prompt plus agent work: no
        // genuine user message and no transcript system row crossed into the
        // summarizer input.
        let seen = mock.seen_messages();
        assert_eq!(seen[0].role, "system");
        assert_eq!(seen[0].content, SUMMARY_SYSTEM_PROMPT);
        assert_eq!(
            seen[1..]
                .iter()
                .filter(|m| {
                    m.content.contains("turn one request") || m.content.contains("turn two request")
                })
                .count(),
            0,
            "genuine user rows must stay out of the summarizer input: {seen:?}"
        );
        assert!(
            seen[1..].iter().all(|m| m.role != "system"),
            "only the fixed summarization prompt may be a system row: {seen:?}"
        );
    }

    #[tokio::test]
    async fn compact_history_falls_back_without_mutating_history() {
        let mut history = long_history();
        let original = history.clone();
        let mock = MockSummarizer::error();
        let outcome = compact_history(
            &mut history,
            false,
            6,
            &enabled_config(),
            &mock,
            "custom.default",
            "m-main",
        )
        .await;
        assert!(outcome.is_none(), "summarizer failure must fall back (I4)");
        assert_eq!(
            history_json(&history),
            history_json(&original),
            "fallback leaves history untouched"
        );
    }

    #[tokio::test]
    async fn compact_history_falls_back_when_summary_exceeds_budget() {
        let mut history = long_history();
        let original = history.clone();
        let mut mock = MockSummarizer::text("a summary far over the cap");
        mock.usage_output_tokens = Some(9_999);
        let cfg = ContextCompressionConfig {
            summary_max_output_tokens: 500,
            ..enabled_config()
        };
        let outcome = compact_history(
            &mut history,
            false,
            6,
            &cfg,
            &mock,
            "custom.default",
            "m-main",
        )
        .await;
        assert!(
            outcome.is_none(),
            "reported output over the budget must fall back (FR7)"
        );
        assert_eq!(history_json(&history), history_json(&original));
    }

    #[tokio::test]
    async fn compact_history_is_disabled_by_default_byte_identical() {
        let mut history = long_history();
        let original = history.clone();
        let mock = MockSummarizer::text("should never be used");
        let outcome = compact_history(
            &mut history,
            false,
            6,
            &ContextCompressionConfig::default(),
            &mock,
            "custom.default",
            "m-main",
        )
        .await;
        assert!(outcome.is_none());
        assert_eq!(history_json(&history), history_json(&original));
        assert!(
            mock.seen_messages().is_empty(),
            "disabled compaction must not issue an LLM call (I3)"
        );
    }

    #[tokio::test]
    async fn compact_history_persists_through_serde_roundtrip() {
        // FR5 / NFR3: the summary is an ordinary transcript row, so it must
        // survive session persistence and never be re-generated on reload.
        let mut history = long_history();
        let mock = MockSummarizer::text("I have done the earlier work.");
        compact_history(
            &mut history,
            false,
            6,
            &enabled_config(),
            &mock,
            "custom.default",
            "m-main",
        )
        .await
        .expect("compaction succeeds");
        let serialized = serde_json::to_string(&history).expect("history serializes");
        let reloaded: Vec<ChatMessage> =
            serde_json::from_str(&serialized).expect("history reloads");
        assert_eq!(history_json(&history), history_json(&reloaded));
        assert_eq!(
            reloaded.iter().filter(|m| is_compaction_summary(m)).count(),
            1,
            "exactly one summary marker survives persistence"
        );
    }

    #[tokio::test]
    async fn compact_history_folds_older_summaries_into_new_ones() {
        // A previous compaction's summary row inside a later span is
        // synthetic: it must be re-summarized, not kept verbatim forever.
        let mut history = long_history();
        let mock = MockSummarizer::text("first summary");
        compact_history(
            &mut history,
            false,
            4,
            &enabled_config(),
            &mock,
            "custom.default",
            "m-main",
        )
        .await
        .expect("first compaction succeeds");
        let summaries = history.iter().filter(|m| is_compaction_summary(m)).count();
        assert_eq!(summaries, 1);

        // Second trim drops everything up to the newest turn, including the
        // first summary row.
        let span_len = history.len() - 2;
        let mock2 = MockSummarizer::text("second summary");
        compact_history(
            &mut history,
            false,
            span_len,
            &enabled_config(),
            &mock2,
            "custom.default",
            "m-main",
        )
        .await
        .expect("second compaction succeeds");
        let summaries = history.iter().filter(|m| is_compaction_summary(m)).count();
        assert_eq!(
            summaries, 1,
            "the old summary row must fold into the new one, not stack"
        );
    }

    // ── Story 1.5: planner resolution, event payload ────────────────

    /// Minimal config fixture: agent `alpha` on runtime profile `fast` whose
    /// context_compression block is enabled.
    fn compaction_config_toml(cc_block: &str) -> String {
        format!(
            r#"
            [providers.models.custom.default]
            api_key = "k"
            model = "m-main"
            uri = "https://example.com/v1"
            wire_api = "chat_completions"
            [providers.models.custom.cheap]
            api_key = "k"
            model = "m-cheap"
            uri = "https://example.com/v1"
            wire_api = "chat_completions"

            [risk_profiles.default]
            level = "supervised"

            [runtime_profiles.fast.context_compression]
            {cc_block}

            [agents.alpha]
            enabled = true
            model_provider = "custom.default"
            risk_profile = "default"
            runtime_profile = "fast"
            "#
        )
    }

    #[test]
    fn planner_resolves_enabled_profile_and_stays_disabled_otherwise() {
        let cfg: zeroclaw_config::schema::Config = toml::from_str(&compaction_config_toml(
            "enabled = true\ntrigger_tokens = 64",
        ))
        .unwrap();
        let planner = CompactionPlanner::resolve(Some(&cfg), Some("alpha"));
        assert!(planner.is_enabled());
        assert_eq!(
            planner.provider_label("custom.default", "m-main"),
            "custom.default/m-main",
            "no override: the turn's own route serves the summary"
        );

        // Disabled profile -> inert planner (I3).
        let cfg: zeroclaw_config::schema::Config =
            toml::from_str(&compaction_config_toml("enabled = false")).unwrap();
        assert!(!CompactionPlanner::resolve(Some(&cfg), Some("alpha")).is_enabled());

        // No config / no agent alias / unknown agent -> inert.
        assert!(!CompactionPlanner::resolve(None, Some("alpha")).is_enabled());
        assert!(!CompactionPlanner::resolve(Some(&cfg), None).is_enabled());
        assert!(!CompactionPlanner::resolve(Some(&cfg), Some("nobody")).is_enabled());
    }

    #[test]
    fn planner_routes_summary_provider_override() {
        let cfg: zeroclaw_config::schema::Config = toml::from_str(&compaction_config_toml(
            "enabled = true\nsummary_provider = \"custom.cheap\"",
        ))
        .unwrap();
        let planner = CompactionPlanner::resolve(Some(&cfg), Some("alpha"));
        assert!(planner.is_enabled());
        assert_eq!(
            planner.provider_label("custom.default", "m-main"),
            "custom.cheap/m-cheap",
            "the override alias and its own model must label the summary route"
        );

        // Agent-level override beats the profile-level ref
        // (effective_summary_provider precedence).
        let toml_with_agent_override =
            compaction_config_toml("enabled = true\nsummary_provider = \"custom.cheap\"")
                + "\nsummary_provider = \"custom.default\"\n";
        let cfg: zeroclaw_config::schema::Config =
            toml::from_str(&toml_with_agent_override).unwrap();
        let planner = CompactionPlanner::resolve(Some(&cfg), Some("alpha"));
        assert_eq!(
            planner.provider_label("custom.default", "m-main"),
            "custom.default/m-main",
        );
    }

    #[test]
    fn event_info_maps_summary_and_fallback_modes() {
        let mut history = long_history();
        let mock = MockSummarizer::text("I have established the plan.");
        let outcome = tokio::runtime::Builder::new_current_thread()
            .build()
            .expect("runtime")
            .block_on(compact_history(
                &mut history,
                false,
                6,
                &enabled_config(),
                &mock,
                "custom.default",
                "m-main",
            ))
            .expect("compaction succeeds");
        let info = event_info(&outcome);
        assert_eq!(info.mode, "summary");
        assert!(!info.fell_back);
        assert_eq!(info.span_messages, 6);
        assert!(info.span_tokens > 0);
        assert_eq!(info.summary_tokens, 120);
        assert_eq!(info.kept_user_messages, 2);
        assert_eq!(info.provider, "custom.default/m-main");

        let fallback =
            CompactionOutcome::breadcrumb_fallback(4, 0, "custom.default/m-main".to_string());
        let info = event_info(&fallback);
        assert_eq!(info.mode, "breadcrumb");
        assert!(info.fell_back);
        assert_eq!(info.span_messages, 4);
        assert_eq!(info.summary_tokens, 0);
    }
}
